  --shadow: 0 6px 24px rgba(20,20,15,.06);
  --shadow-lg: 0 24px 60px rgba(20,20,15,.10);
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: 0; background: none; color: inherit; }
h1, h2, h3, h4 { font-family: 'Fraunces', Georgia, serif; font-weight: 600; letter-spacing: -.01em; margin: 0; color: var(--ink); }
h1 { font-size: clamp(2.4rem, 5.5vw, 4.4rem); line-height: 1.02; }
h2 { font-size: clamp(1.6rem, 3vw, 2.4rem); line-height: 1.1; }
h3 { font-size: 1.15rem; line-height: 1.25; }
p  { margin: .5rem 0; color: var(--ink-soft); }

.container { max-width: 1240px; margin: 0 auto; padding: 0 24px; }
.eyebrow { display:inline-block; font-size:.75rem; letter-spacing:.18em; text-transform:uppercase; color: var(--accent-ink); font-weight:600; margin-bottom:.75rem; }
.eyebrow.light { color: #d8c2b3; }
.muted { color: var(--muted); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items:center; justify-content:center; gap:.5rem;
  padding: .85rem 1.4rem; border-radius: 999px;
  font-weight: 600; font-size: .95rem;
  transition: transform .15s ease, background .2s ease, color .2s ease, border-color .2s ease;
  border: 1px solid transparent;
}
.btn-primary { background: var(--ink); color: #fff; }
.btn-primary:hover { background: var(--accent); transform: translateY(-1px); }
.btn-ghost { color: var(--ink); }
