.btn-light { background:#fff; color: var(--ink); }
.btn-light:hover { background: var(--accent); color:#fff; }

.icon-btn { width: 40px; height: 40px; display:inline-flex; align-items:center; justify-content:center; border-radius: 50%; color: var(--ink); position:relative; transition: background .2s; }
