+  background: var(--ink); color:#fff; padding: .7rem; border-radius: 999px;
+  font-size:.85rem; font-weight: 600; opacity: 0; transform: translateY(8px);
+  transition: opacity .25s ease, transform .25s ease, background .2s;
+}
+.product:hover .quick-add { opacity: 1; transform: translateY(0); }
+.quick-add:hover { background: var(--accent); }
+
+.product-name { font-size:.98rem; font-weight: 500; margin: 0 0 4px; }
+.product-meta { display:flex; justify-content:space-between; align-items:center; font-size:.92rem; color: var(--ink-soft); }
+.price { color: var(--ink); font-weight: 600; }
+.price .old { text-decoration: line-through; color: var(--muted); font-weight: 400; margin-right: 6px; }
+.swatches { display:flex; gap: 4px; margin-top: 8px; }
+.swatch { width: 14px; height: 14px; border-radius: 50%; border: 1px solid var(--line); }
+
+/* ---------- Deals ---------- */
+.deals { background: var(--sand); }
+.countdown { display: flex; gap: .5rem; }
+.countdown > div {
+  background: #fff; min-width: 60px; padding: .5rem .7rem; border-radius: var(--radius-sm);
+  text-align:center; box-shadow: var(--shadow);
+}
+.countdown span {
+  display:block; font-family: 'Fraunces', serif; font-size: 1.4rem; font-weight: 600; line-height: 1;
+}
+.countdown small { font-size:.65rem; letter-spacing:.1em; color: var(--muted); text-transform: uppercase; }
+
+.deals-grid {
+  display: grid; grid-template-columns: 2fr 1fr 1fr; grid-template-rows: 1fr 1fr; gap: 20px;
+  min-height: 520px;
+}
+.deal {
+  position: relative; overflow: hidden; border-radius: var(--radius);
+  background:#fff; display: flex; flex-direction: column;
+  transition: transform .25s ease, box-shadow .25s ease;
+}
+.deal:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
+.deal-large { grid-row: span 2; }
+.deal-img { flex: 1; background-size: cover; background-position: center; min-height: 180px; }
+.deal-large .deal-img { min-height: 320px; }
+.deal-body { padding: 22px; }
+.deal-tag {
+  display:inline-block; background: var(--accent); color:#fff; font-size:.75rem; font-weight: 700;
+  padding: 4px 10px; border-radius: 999px; margin-bottom: 10px; letter-spacing:.05em;
+}
+.deal-body h3 { font-size: 1.3rem; margin-bottom: 6px; }
+.deal-large .deal-body h3 { font-size: 1.7rem; }
+.link-arrow { font-weight: 600; font-size:.9rem; color: var(--accent-ink); display:inline-block; margin-top: 10px; transition: transform .2s; }
+.link-arrow:hover { transform: translateX(4px); }
+.link-arrow.muted { color: var(--ink-soft); }
+
+/* ---------- Editorial ---------- */
+.edit-grid {
+  display: grid; grid-template-columns: 1.4fr 1fr 1fr; grid-template-rows: auto auto; gap: 24px;
+}
+.edit-card {
+  background: var(--surface); border-radius: var(--radius); overflow: hidden;
+  display:flex; flex-direction: column; transition: transform .25s, box-shadow .25s;
+}
+.edit-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
+.edit-feature { grid-row: span 2; }
+.edit-img { aspect-ratio: 16/10; background-size: cover; background-position: center; }
+.edit-feature .edit-img { aspect-ratio: 4/3; }
+.edit-body { padding: 22px 24px 26px; }
+.edit-cat { display:inline-block; font-size:.7rem; letter-spacing:.15em; text-transform:uppercase; color: var(--accent); font-weight: 700; margin-bottom: 8px; }
+.edit-card h3 { font-size: 1.2rem; margin-bottom: 8px; }
+.edit-feature h3 { font-size: 1.7rem; line-height: 1.15; }
+.byline { display:block; margin-top: 12px; font-size:.82rem; color: var(--muted); }
+
+/* ---------- Newsletter ---------- */
+.newsletter {
+  background: var(--ink); color: #f0e8df; padding: 70px 0;
+}
+.news-inner {
+  display:grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
+}
+.newsletter h2 { color: #fff; }
+.newsletter p { color: #b6ab9c; max-width: 380px; }
+.news-form { display:flex; gap: 10px; flex-wrap: wrap; position:relative; }
+.news-form input {
+  flex: 1; min-width: 220px; padding: .9rem 1.2rem; border-radius: 999px;
+  border: 1px solid #3a3a34; background: #2a2a25; color: #fff; font-size: .95rem; outline: none;
+  transition: border-color .2s;
+}
+.news-form input:focus { border-color: var(--accent); }
+.news-msg { position:absolute; bottom: -22px; left: 18px; color: #c8d8b8; font-size:.8rem; }
+
+/* ---------- Footer ---------- */
+.site-footer { background: #f3f0e8; padding: 60px 0 30px; color: var(--ink-soft); }
+.footer-grid { display:grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 40px; }
+.site-footer h4 { font-family: 'Inter', sans-serif; font-size:.78rem; letter-spacing:.15em; text-transform: uppercase; color: var(--ink); margin-bottom: 16px; }
+.site-footer a { display: block; padding: 5px 0; font-size:.92rem; transition: color .2s; }
+.site-footer a:hover { color: var(--accent); }
+.footer-bottom { display:flex; justify-content:space-between; padding-top: 24px; border-top: 1px solid var(--sand-2); font-size:.8rem; color: var(--muted); }
+
+/* ---------- Toast ---------- */
+.toast {
+  position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%) translateY(20px);
+  background: var(--ink); color: #fff; padding: .9rem 1.4rem; border-radius: 999px;
+  font-size:.9rem; font-weight: 500; box-shadow: var(--shadow-lg);
+  opacity: 0; pointer-events: none; transition: opacity .25s, transform .25s; z-index: 100;
+}
+.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
+
+/* ---------- Responsive ---------- */
+@media (max-width: 980px) {
+  .hero-grid { grid-template-columns: 1fr; gap: 40px; }
+  .hero-visual { height: 460px; }
+  .cat-grid { grid-template-columns: repeat(3, 1fr); }
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
+  .deal-large { grid-row: auto; grid-column: span 2; }
+  .edit-grid { grid-template-columns: 1fr 1fr; }
+  .edit-feature { grid-row: auto; grid-column: span 2; }
+  .news-inner, .footer-grid { grid-template-columns: 1fr 1fr; gap: 30px; }
+  .primary-nav {
+    position: fixed; inset: 70px 0 auto 0; flex-direction: column; gap: 0;
+    background: var(--bg); border-bottom: 1px solid var(--line); padding: 20px 24px;
+    transform: translateY(-120%); transition: transform .3s ease;
+  }
+  .primary-nav.open { transform: translateY(0); }
+  .primary-nav a { padding: 12px 0; border-bottom: 1px solid var(--line); width: 100%; }
+  .menu-btn { display: inline-flex; }
+  .header-inner { grid-template-columns: 1fr auto 1fr; }
+}
+@media (max-width: 600px) {
+  h1 { font-size: 2.4rem; }
+  .section { padding: 50px 0; }
+  .cat-grid { grid-template-columns: repeat(3, 1fr); }
+  .deals-grid { grid-template-columns: 1fr; }
+  .deal-large { grid-column: auto; }
+  .edit-grid { grid-template-columns: 1fr; }
+  .edit-feature { grid-column: auto; }
+  .news-inner, .footer-grid { grid-template-columns: 1fr; }
+  .footer-bottom { flex-direction: column; gap: 8px; align-items: flex-start; }
+  .countdown > div { min-width: 50px; }
+}
+
